import{_ as i,o as a,a as l,b as e}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"HCCL通信类","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_communication"},{"text":"HCCL核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Kernel/HCCL_Kernel"},{"text":"Init（废弃）","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_Kernel/Init_deprecated"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Kernel/Init_deprecated.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Kernel/Init_deprecated.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1787132628000}'),n={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_Kernel/Init_deprecated.md"};function d(r,t,c,s,h,o){return a(),l("div",null,[...t[0]||(t[0]=[e(`<div><article class="markdown-body"><h1>Init（废弃）</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>该接口废弃，并将在后续版本移除，请不要使用该接口。请使用<a href="InitV2.html">InitV2</a>接口进行初始化。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>HCCL客户端初始化接口。该接口默认在所有核上工作，用户也可以在调用前通过<a href="../../../basic_api/tool_interface/system_resources_and_variables/GetBlockIdx.html">GetBlockIdx</a>指定其在某一个核上运行。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__aicore__ inline void Init(GM_ADDR context, __gm__ void* initTiling = nullptr)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>context</td><td>输入</td><td>通信上下文，包含rankDim，rankID等相关信息。</td></tr><tr><td>initTiling</td><td>输入</td><td>可选参数，通信域初始化<a href="../HCCL_Tiling/TilingData_struct.html#table4835205712588">Mc2InitTiling</a>的地址。<a href="../HCCL_Tiling/TilingData_struct.html#table4835205712588">Mc2InitTiling</a>在Host侧计算得出，具体请参考<a href="../HCCL_Tiling/TilingData_struct.html#table4835205712588">表1 Mc2InitTiling参数说明</a>，由框架传递到核函数（Kernel）中使用，完整示例请参考<a href="HCCL_template_params.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">8.13.1.2-调用示例</a>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>若调用本接口时传入initTiling参数，则必须与<a href="SetCcTiling_deprecated.html">SetCcTiling</a>接口配合使用。</li><li>同一个程序中不能同时调用传入可选参数initTiling的接口和不传入可选参数initTiling的接口，推荐使用传入initTiling参数的调用方式。</li><li>若调用本接口时传入initTiling参数，必须使用标准C++语法定义TilingData结构体的开发方式。</li><li>本接口不支持使用相同的context初始化多个HCCL对象。每个HCCL对象都应获取其自身的通信上下文。</li></ul></article></div>`,1)])])}const C=i(n,[["render",d]]);export{p as __pageData,C as default};
